ddl:
CREATE TABLE Language (
    ISO_code VARCHAR(255),
    language_ID INTEGER PRIMARY KEY,
    language_name VARCHAR(255)
);

CREATE TABLE Country (
    ISO_code VARCHAR(255),
    country_ID INTEGER PRIMARY KEY,
    country_name VARCHAR(255)
);

CREATE TABLE Application (
    application_ID INTEGER PRIMARY KEY,
    application_name VARCHAR(255)
);

CREATE TABLE Region (
    ISO_code VARCHAR(255),
    country_ID INTEGER NOT NULL,
    region_ID INTEGER PRIMARY KEY,
    region_name VARCHAR(255),
    FOREIGN KEY (country_ID) REFERENCES Country(country_ID)
);

CREATE TABLE Resource_File (
    application_ID INTEGER NOT NULL,
    base_name VARCHAR(255),
    path VARCHAR(255),
    resource_file_ID INTEGER PRIMARY KEY,
    version VARCHAR(255),
    FOREIGN KEY (application_ID) REFERENCES Application(application_ID)
);

CREATE TABLE Application_and_Language (
    application_ID INTEGER NOT NULL,
    language_ID INTEGER NOT NULL,
    PRIMARY KEY (application_ID, language_ID),
    FOREIGN KEY (application_ID) REFERENCES Application(application_ID),
    FOREIGN KEY (language_ID) REFERENCES Language(language_ID)
);

CREATE TABLE Language_and_Region (
    language_ID INTEGER NOT NULL,
    region_ID INTEGER NOT NULL,
    PRIMARY KEY (language_ID, region_ID),
    FOREIGN KEY (language_ID) REFERENCES Language(language_ID),
    FOREIGN KEY (region_ID) REFERENCES Region(region_ID)
);

CREATE TABLE Resource_Key (
    key_ID INTEGER PRIMARY KEY,
    key_name VARCHAR(255),
    resource_file_ID INTEGER NOT NULL,
    version VARCHAR(255),
    FOREIGN KEY (resource_file_ID) REFERENCES Resource_File(resource_file_ID)
);

CREATE TABLE Resource_Value (
    key_ID INTEGER NOT NULL,
    value_ID INTEGER PRIMARY KEY,
    value_content VARCHAR(255),
    version VARCHAR(255),
    FOREIGN KEY (key_ID) REFERENCES Resource_Key(key_ID)
);
